<?php
/** Saved progress/cache diagnostics on synthetic disposable records only. */
declare(strict_types=1);
if(!defined('TGIT_DISPOSABLE_TEST_SITE')||TGIT_DISPOSABLE_TEST_SITE!==true)throw new RuntimeException('Disposable site required.');

test('Tickerbot diagnostics retain partial batch outcomes without changing requests or ledger',function()use($tracker){
 [$s,$w,$scope,$now,$run,$ids]=tbw_context(2);\GainerInteractive\IGTradingJournal\Infrastructure\TickerbotRefresh::step($s,$w,$run['run_id'],$run['lease_token'],fn($url)=>tbw_response($url,['S1']));$before=$s->usage($w);$read=$s->diagnostics($w);equal($read['run']['state'],'failed');equal($read['plan_saved'],true);equal($read['counted_attempts'],1);equal(count($read['batches']),1);equal($read['batches'][0]['received_assets'],1);equal($read['batches'][0]['issues'],['unsupported'=>1]);equal($read['marks'][1]['mark'],null);equal($s->usage($w),$before);equal(count($tracker->list_objects($w,'transactions')),0);foreach(['lease_token','request_key','scope_digest','correlation_id','fingerprint']as$key)equal(str_contains(json_encode($read),'"'.$key.'"'),false);
});
test('Tickerbot diagnostics distinguish expired saved running state without lease recovery or admission',function()use($db,$owner){
 [$s,$w,$scope,$now,$run]=tbw_context();$later=new \GainerInteractive\IGTradingJournal\Application\TickerbotStore($db,$owner,wp_generate_uuid4(),$scope,$now->modify('+6 minutes'));$read=$later->diagnostics($w);equal($read['run']['state'],'running');equal($read['run']['lease_status'],'expired');equal($read['batches'][0]['state'],'pending');equal($read['counted_attempts'],0);equal($s->readiness($w)['latest_run']['state'],'running');
});
test('Tickerbot repeated receipts cannot rejuvenate old source times and provenance remains selective',function()use($db,$owner){
 [$s,$w,$scope,$now,$run,$ids]=tbw_context();$old=$now->modify('-8 hours')->format('Y-m-d\TH:i:s\Z');$send=function($url)use($old){$r=tbw_response($url);$body=json_decode($r['body'],true);$body['data']['price_asof']=$old;$r['body']=json_encode($body);return $r;};\GainerInteractive\IGTradingJournal\Infrastructure\TickerbotRefresh::step($s,$w,$run['run_id'],$run['lease_token'],$send);$quote=$s->latest_quote($w,$ids[0]);$laterTime=$now->modify('+6 minutes');$later=new \GainerInteractive\IGTradingJournal\Application\TickerbotStore($db,$owner,wp_generate_uuid4(),$scope,$laterTime);$new=$later->start_run($w,'repeat-old-mark');$a=$later->reserve_attempt($w,$new['run_id'],$new['lease_token'],'quotes',[$quote['provider_symbol']]);$quote['asset_id']=$ids[0];$quote['fetched_at']=$laterTime->format('Y-m-d H:i:s.u');$later->record_quote($w,$new['run_id'],$new['lease_token'],$a['attempt_id'],(int)$quote['mapping_id'],$quote);$later->finish_attempt($w,$new['run_id'],$new['lease_token'],$a['attempt_id'],'completed');$later->finish_run($w,$new['run_id'],$new['lease_token'],'completed');$read=$later->diagnostics($w);$mark=$read['marks'][0]['mark'];equal($mark['age']['state'],'stale');equal($mark['last_received_at'],$quote['fetched_at']);equal($mark['price_asof'],$quote['price_asof']);equal($mark['source_time_semantics'],'provider_fetch_time');equal(array_keys($mark),['price','currency','price_source','source_time_semantics','price_asof','response_as_of','last_received_at','age']);
});
test('Tickerbot diagnostics preserve unknown source time and exclude another account cache and run',function()use($db,$owner){
 [$s,$w,$scope,$now,$run,$ids]=tbw_context();$send=function($url){$r=tbw_response($url);$body=json_decode($r['body'],true);$body['data']['price_asof']=null;$r['body']=json_encode($body);return $r;};\GainerInteractive\IGTradingJournal\Infrastructure\TickerbotRefresh::step($s,$w,$run['run_id'],$run['lease_token'],$send);equal($s->diagnostics($w)['marks'][0]['mark']['age']['state'],'unknown');$other=new \GainerInteractive\IGTradingJournal\Application\TickerbotStore($db,$owner,wp_generate_uuid4(),'other-account-'.wp_generate_uuid4(),$now);equal($other->latest_quote($w,$ids[0]),null);tbs_denied(fn()=>$other->diagnostics($w));
});
test('Tickerbot diagnostics are owner scoped and connection checks do not hide the quote run',function()use($db,$owner,$viewer,$tracker){
 [$s,$w,$scope,$now,$run]=tbw_context();$s->finish_run($w,$run['run_id'],$run['lease_token'],'failed');$later=new \GainerInteractive\IGTradingJournal\Application\TickerbotStore($db,$owner,wp_generate_uuid4(),$scope,$now->modify('+6 minutes'));$connection=$later->start_run($w,'new-connection','connection');$later->finish_run($w,$connection['run_id'],$connection['lease_token'],'failed');equal($later->diagnostics($w)['run']['cause'],'manual');$untrusted=new \GainerInteractive\IGTradingJournal\Application\TickerbotStore($db,$viewer,wp_generate_uuid4(),$scope,$now);tbs_denied(fn()=>$untrusted->diagnostics($w));$foreign=(int)$tracker->create_workspace(['name'=>'Other diagnostics'])['id'];tbs_denied(fn()=>$s->diagnostics($foreign));
});

test('Tickerbot diagnostics route is owner-only local and keeps shared usage unchanged',function()use($tracker,$db,$owner,$viewer){
 $w=(int)$tracker->create_workspace(['name'=>'Diagnostics route'])['id'];$s=\GainerInteractive\IGTradingJournal\Infrastructure\TickerbotSetup::service($db,$owner,$w,wp_generate_uuid4());$account=$db->row('SELECT monthly_cap FROM '.$db->table('tickerbot_accounts').' WHERE scope_digest=%s',[hash('sha256','tickerbot/account/'.TGIT_TICKERBOT_ACCOUNT_SCOPE)]);$s->configure($w,(int)$account['monthly_cap']);$before=$s->usage($w);$calls=0;$fake=function()use(&$calls){$calls++;return new WP_Error('fixture_blocked','No HTTP');};add_filter('pre_http_request',$fake,1);$r=new WP_REST_Request('GET','/tgit/v1/workspaces/'.$w.'/tickerbot/diagnostics');$r->set_url_params(['workspace'=>(string)$w]);try{wp_set_current_user($owner);$result=\GainerInteractive\IGTradingJournal\Http\Controller::dispatch($r,'tickerbot_diagnostics');equal($result instanceof WP_REST_Response,true);equal($result->get_data()['data']['run'],null);equal($result->get_data()['data']['complete'],true);equal($s->usage($w),$before);equal($calls,0);wp_set_current_user($viewer);equal(is_wp_error(\GainerInteractive\IGTradingJournal\Http\Controller::dispatch($r,'tickerbot_diagnostics')),true);}finally{wp_set_current_user($owner);remove_filter('pre_http_request',$fake,1);}
});
